#include <stdio.h>

void reverse(int a[], int from, int to) {
    while (from < to) {
        int t = a[from];
        a[from++] = a[to];
        a[to--] = t;
    }
}

int main() {
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    int n = 7, k = 3;
    reverse(a, 0, k - 1);
    reverse(a, k, n - 1);
    reverse(a, 0, n - 1);
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
